// Catalog model, indexes, search and lookups for the Spanish public data catalog.
//
// The data is a committed copy of `catalog.json` generated by
// BquantFinance/Administracion-fuentes-publicas. Refresh it with
// `npm run data:sync`; never edit `src/data/catalog.json` by hand.

import catalogData from '../data/catalog.json';

export interface Endpoint {
	path: string;
	desc: string;
}

export interface Check {
	url: string;
	contains: string;
}

export interface RecipeStep {
	source: string;
	do: string;
	example?: string;
}

export interface Recipe {
	id: string;
	intent: string;
	inputs: string[];
	steps: RecipeStep[];
	output: string;
	checks?: Check[];
	verified?: string;
	note?: string;
}

export interface Product {
	id: string;
	producto: string;
	cliente: string;
	fuentes: string[];
	recetas: string[];
	piezas: string;
	frescura: string;
	volumen: string;
	licencia: string;
	trampa: string;
	verified: string;
}

export interface Need {
	need: string;
	source: string | null;
	note?: string;
}

export interface IdentifierJoin {
	via: string;
	how: string;
}

export interface Identifier {
	format: string;
	regex?: string;
	example?: string;
	issuer?: string;
	gotcha?: string;
	joins?: IdentifierJoin[];
	used_by?: string[];
}

export interface DeadRoute {
	old: string;
	status: string | number;
	new?: string;
	source?: string;
	note?: string;
	checked?: string;
}

export interface CodeEntry {
	code: string;
	name?: string;
	note?: string;
}

export interface CodeGroup {
	source: string;
	use: string;
	verified?: string;
	note?: string;
	entries: CodeEntry[];
}

export interface SourceCode {
	module: string;
	use: string[];
	mcp?: string[];
}

export interface SourceSync {
	since?: string;
	full?: string;
	size?: string;
	new?: string;
}

export interface Source {
	id: string;
	name: string;
	org: string;
	level: string;
	sector: string;
	ministry?: string;
	tags: string[];
	summary: string;
	access: string[];
	auth: string;
	formats: string[];
	update: string;
	coverage: string;
	license: string;
	base_url: string;
	docs_url?: string;
	endpoints: Endpoint[];
	quirks?: string[];
	ids?: string[];
	gotchas?: string[];
	tips?: string[];
	related?: string[];
	status: string;
	verified?: string | null;
	alerts?: string[];
	code?: SourceCode;
	sync?: SourceSync;
	rate_limit?: string;
}

export interface CatalogIndices {
	productos: Product[];
	recetas: Recipe[];
	necesidades: Need[];
	identificadores: Record<string, Identifier>;
	rutas_muertas: DeadRoute[];
	codigos: Record<string, CodeGroup>;
}

export interface Catalog {
	name: string;
	description: string;
	generated: string;
	repo: string;
	schema: string;
	vocab: string;
	count: number;
	sectors: Record<string, string>;
	sources: Source[];
	indices: CatalogIndices;
}

const catalog = catalogData as unknown as Catalog;

export const CATALOG = catalog;
export const SOURCES = catalog.sources;
export const SECTORS = catalog.sectors;
export const SOURCE_BY_ID = new Map(SOURCES.map((source) => [source.id, source]));
export const PRODUCTS = catalog.indices.productos;
export const PRODUCT_BY_ID = new Map(PRODUCTS.map((product) => [product.id, product]));
export const RECIPES = catalog.indices.recetas;
export const RECIPE_BY_ID = new Map(RECIPES.map((recipe) => [recipe.id, recipe]));
export const NEEDS = catalog.indices.necesidades;
export const IDENTIFIERS = catalog.indices.identificadores;
export const DEAD_ROUTES = catalog.indices.rutas_muertas;
export const CODE_GROUPS = catalog.indices.codigos;

export const LEVELS = ['age', 'ccaa', 'local'] as const;
export const STATUSES = ['active', 'degraded', 'unknown'] as const;

