/** Lowercase, strip accents, flatten arrays and objects to text. */
export function norm(value: unknown): string {
	if (Array.isArray(value)) return value.map((item) => norm(item)).join(' ');
	if (value && typeof value === 'object') {
		return norm(Object.values(value as Record<string, unknown>));
	}
	return String(value ?? '')
		.normalize('NFKD')
		.replace(/[\u0300-\u036f]/g, '')
		.toLowerCase();
}

/** Query tokens, without stopwords and single characters. */
export function tokens(query: string): string[] {
	const base = norm(query)
		.split(/[^a-z0-9]+/)
		.filter((token) => token.length > 1 && !STOPWORDS.has(token));

	const expanded: string[] = [];
	for (const token of base) {
		expanded.push(token);
		for (const synonym of SYNONYMS[token] ?? []) {
			for (const part of synonym.split(/\s+/)) {
				if (part.length > 1 && !STOPWORDS.has(part) && !expanded.includes(part)) expanded.push(part);
			}
		}
	}
	return expanded;
}

/** The token and its short prefixes: gasolina matches gasolinera, municipios matches municipio. */
export function variants(token: string): string[] {
	const out = [token];
	if (token.length >= 5) out.push(token.slice(0, -1));
	if (token.length >= 7) out.push(token.slice(0, -2));
	return out;
}

export interface Score {
	matched: number;
	points: number;
}

/** `(tokens matched, points)`; strong fields score 3, weak fields score 1. */
export function score(query: string, strong: string, weak: string): Score {
	let matched = 0;
	let points = 0;
	for (const token of tokens(query)) {
		const parts = variants(token);
		if (parts.some((part) => strong.includes(part))) {
			matched += 1;
			points += 3;
		} else if (parts.some((part) => weak.includes(part))) {
			matched += 1;
			points += 1;
		}
	}
	return { matched, points };
}

interface Fields {
	strong: string;
	weak: string;
}

function rank<T>(query: string, items: T[], fields: (item: T) => Fields, limit: number): T[] {
	const wanted = tokens(query);
	const cap = Math.max(1, Math.min(limit, 50));
	if (wanted.length === 0) return items.slice(0, cap);

	const scored: Array<{ item: T; matched: number; points: number }> = [];
	for (const item of items) {
		const field = fields(item);
		const result = score(query, field.strong, field.weak);
		if (result.matched > 0) scored.push({ item, ...result });
	}
	scored.sort((a, b) => b.matched - a.matched || b.points - a.points);
	return scored.slice(0, cap).map((entry) => entry.item);
}

/** Dice coefficient over character bigrams; used for "did you mean" suggestions. */
function similarity(a: string, b: string): number {
	const left = norm(a);
	const right = norm(b);
	if (left === right) return 1;
	if (left.length < 2 || right.length < 2) return 0;
	const bigrams = new Map<string, number>();
	for (let index = 0; index < left.length - 1; index += 1) {
		const gram = left.slice(index, index + 2);
		bigrams.set(gram, (bigrams.get(gram) ?? 0) + 1);
	}
	let hits = 0;
	for (let index = 0; index < right.length - 1; index += 1) {
		const gram = right.slice(index, index + 2);
		const count = bigrams.get(gram) ?? 0;
		if (count > 0) {
			bigrams.set(gram, count - 1);
			hits += 1;
		}
	}
	return (2 * hits) / (left.length - 1 + right.length - 1);
}

/** Similar ids: first by shared id segments, then by text similarity. */
export function similarIds(id: string, candidates: Iterable<string>, limit = 5): string[] {
	const wanted = norm(id);
	const parts = wanted.split(/[^a-z0-9]+/).filter((part) => part.length > 2);
	const scored: Array<{ id: string; hits: number; ratio: number }> = [];
	for (const candidate of candidates) {
		const segments = norm(candidate).split(/[^a-z0-9]+/);
		const hits = parts.reduce((total, part) => total + (segments.some((segment) => segment.startsWith(part)) ? 1 : 0), 0);
		const ratio = similarity(wanted, candidate);
		if (hits > 0 || ratio >= 0.5) scored.push({ id: candidate, hits, ratio });
	}
	scored.sort((a, b) => b.hits - a.hits || b.ratio - a.ratio || a.id.localeCompare(b.id));
	return scored.slice(0, limit).map((entry) => entry.id);
}

function sourceFields(source: Source): Fields {
	return {
		strong: norm([source.id, source.name, source.tags, source.sector, SECTORS[source.sector]]),
		weak: norm([
			source.summary,
			source.org,
			source.ministry,
			source.ids,
			source.access,
			source.formats,
			source.coverage,
			source.update,
		]),
	};
}

function recipeFields(recipe: Recipe): Fields {
	return {
		strong: norm([recipe.id, recipe.intent, recipe.steps.map((step) => step.source)]),
		weak: norm([recipe.inputs, recipe.steps.map((step) => step.do), recipe.output, recipe.note]),
	};
}

const SOURCE_FIELDS = new Map(SOURCES.map((source) => [source.id, sourceFields(source)]));
const RECIPE_FIELDS = new Map(RECIPES.map((recipe) => [recipe.id, recipeFields(recipe)]));

export function sectorLabel(id: string): string | undefined {
	return SECTORS[id];
}

export function codePointer(code: SourceCode | undefined): string | undefined {
	if (!code) return undefined;
	const short = code.module.split('.').pop() ?? code.module;
	return short === 'consulta' && code.mcp?.length ? code.mcp[0] : `clientes.${short}`;
}

/** A compact source row, sized for agent context rather than for humans. */
export function compactSource(source: Source) {
	return {
		id: source.id,
		name: source.name,
		org: source.org,
		level: source.level,
		sector: source.sector,
		sector_label: SECTORS[source.sector],
		access: source.access,
		auth: source.auth,
		formats: source.formats,
		update: source.update,
		status: source.status,
		verified: source.verified ?? null,
		summary: source.summary,
		...(source.code ? { code: codePointer(source.code) } : {}),
		...(source.alerts ? { alerts: source.alerts } : {}),
	};
}

export interface SourceFilter {
	sector?: string;
	level?: string;
	status?: string;
	access?: string;
	format?: string;
	auth?: string;
}

export function filterSources(filter: SourceFilter = {}): Source[] {
	return SOURCES.filter((source) => {
		if (filter.sector && source.sector !== filter.sector) return false;
		if (filter.level && source.level !== filter.level) return false;
		if (filter.status && source.status !== filter.status) return false;
		if (filter.auth && source.auth !== filter.auth) return false;
		if (filter.access && !source.access.includes(filter.access)) return false;
		if (filter.format && !source.formats.includes(filter.format)) return false;
		return true;
	});
}

export interface SearchOptions extends SourceFilter {
	query: string;
	limit?: number;
}

/** Search sources, recipes, needs, products and identifiers at once. */
export function searchCatalog(options: SearchOptions) {
	const limit = Math.max(1, Math.min(options.limit ?? 5, 50));
	const pool = filterSources(options);

	const sources = rank(options.query, pool, (source) => SOURCE_FIELDS.get(source.id) ?? sourceFields(source), limit).map(
		compactSource,
	);

	const recipes = rank(options.query, RECIPES, (recipe) => RECIPE_FIELDS.get(recipe.id) ?? recipeFields(recipe), 3).map(
		(recipe) => ({
			id: recipe.id,
			intent: recipe.intent,
			sources: [...new Set(recipe.steps.map((step) => step.source))],
			verified: recipe.verified ?? null,
		}),
	);

	const needs = rank(
		options.query,
		NEEDS,
		(need) => ({ strong: norm(need.need), weak: norm([need.source, need.note]) }),
		3,
	).map((need) => ({ need: need.need, source: need.source, note: need.note }));

	const products = rank(
		options.query,
		PRODUCTS,
		(product) => ({
			strong: norm([product.id, product.producto]),
			weak: norm([product.cliente, product.fuentes, product.piezas]),
		}),
		3,
	).map((product) => ({ id: product.id, producto: product.producto, fuentes: product.fuentes }));

	const identifiers = rank(
		options.query,
		Object.entries(IDENTIFIERS),
		([id, identifier]) => ({
			strong: norm(id),
			weak: norm([identifier.format, identifier.issuer]),
		}),
		2,
	).map(([id, identifier]) => ({ id, format: identifier.format, example: identifier.example }));

	const result = {
		query: options.query,
		...(sources.length ? { sources } : {}),
		...(recipes.length ? { recipes } : {}),
		...(needs.length ? { needs } : {}),
		...(products.length ? { products } : {}),
		...(identifiers.length ? { identifiers } : {}),
	};

	if (Object.keys(result).length === 1) {
		return {
			...result,
			note:
				'Nothing matched. Try different words, check the sector ids with list_sources, or read catalog://llms-min. ' +
				'If a source is missing, request it at https://github.com/BquantFinance/Administracion-fuentes-publicas/issues/new.',
		};
	}
	return result;
}

export type RecordKind = 'source' | 'recipe' | 'product' | 'identifier' | 'code_group';

export function getRecord(id: string) {
	const source = SOURCE_BY_ID.get(id);
	if (source) {
		// Alerts and the code pointer come first: they are the facts that change a number without raising an error.
		return {
			type: 'source' as RecordKind,
			...(source.alerts ? { alerts: source.alerts } : {}),
			...(source.code ? { code: source.code } : {}),
			...source,
		};
	}

	const recipe = RECIPE_BY_ID.get(id);
	if (recipe) return { type: 'recipe' as RecordKind, ...recipe };

	const product = PRODUCT_BY_ID.get(id);
	if (product) return { type: 'product' as RecordKind, ...product };

	const identifier = IDENTIFIERS[id];
	if (identifier) return { type: 'identifier' as RecordKind, id, ...identifier };

	const codeGroup = CODE_GROUPS[id];
	if (codeGroup) return { type: 'code_group' as RecordKind, group: id, ...codeGroup };

	const candidates = [
		...SOURCE_BY_ID.keys(),
		...RECIPE_BY_ID.keys(),
		...PRODUCT_BY_ID.keys(),
		...Object.keys(IDENTIFIERS),
		...Object.keys(CODE_GROUPS),
	];
	return { error: `No record with id "${id}".`, suggestions: similarIds(id, candidates) };
}

export interface ListSourcesOptions extends SourceFilter {
	query?: string;
	limit?: number;
	offset?: number;
}

export function listSources(options: ListSourcesOptions = {}) {
	const limit = Math.max(1, Math.min(options.limit ?? 25, 100));
	const offset = Math.max(0, options.offset ?? 0);
	const pool = filterSources(options);
	const ordered = options.query
		? rank(options.query, pool, (source) => SOURCE_FIELDS.get(source.id) ?? sourceFields(source), pool.length)
		: pool;

	return {
		total: ordered.length,
		offset,
		limit,
		items: ordered.slice(offset, offset + limit).map(compactSource),
	};
}

export function listProducts(query?: string, limit = 50) {
	const items = query
		? rank(
				query,
				PRODUCTS,
				(product) => ({
					strong: norm([product.id, product.producto]),
					weak: norm([product.cliente, product.fuentes, product.piezas, product.trampa]),
				}),
				limit,
			)
		: PRODUCTS.slice(0, Math.max(1, Math.min(limit, 50)));
	return { total: items.length, items };
}

export function listRecipes(query?: string, source?: string, limit = 50) {
	const pool = source ? RECIPES.filter((recipe) => recipe.steps.some((step) => step.source === source)) : RECIPES;
	const items = query
		? rank(query, pool, (recipe) => RECIPE_FIELDS.get(recipe.id) ?? recipeFields(recipe), limit)
		: pool.slice(0, Math.max(1, Math.min(limit, 50)));

	return {
		total: items.length,
		items: items.map((recipe) => ({
			id: recipe.id,
			intent: recipe.intent,
			sources: [...new Set(recipe.steps.map((step) => step.source))],
			output: recipe.output,
			verified: recipe.verified ?? null,
		})),
	};
}

export interface GetCodesOptions {
	group?: string;
	query?: string;
	limit?: number;
}

export function getCodes(options: GetCodesOptions = {}) {
	const limit = Math.max(1, Math.min(options.limit ?? 50, 500));

	if (options.group) {
		const group = CODE_GROUPS[options.group];
		if (!group) {
			return {
				error: `No code group "${options.group}".`,
				suggestions: similarIds(options.group, Object.keys(CODE_GROUPS)),
			};
		}
		const entries = options.query
			? group.entries.filter((entry) => norm([entry.code, entry.name, entry.note]).includes(norm(options.query ?? '')))
			: group.entries;
		return {
			group: options.group,
			source: group.source,
			use: group.use,
			verified: group.verified ?? null,
			...(group.note ? { note: group.note } : {}),
			total: entries.length,
			entries: entries.slice(0, limit),
		};
	}

	const groups = Object.entries(CODE_GROUPS).map(([id, group]) => ({
		group: id,
		source: group.source,
		use: group.use,
		entries: group.entries.length,
		verified: group.verified ?? null,
	}));

	if (!options.query) {
		return { total: groups.length, groups };
	}

	const query = norm(options.query);
	const matched = groups
		.map((group) => {
			const detail = CODE_GROUPS[group.group];
			const entries = detail.entries.filter((entry) => norm([entry.code, entry.name, entry.note]).includes(query));
			const headerHit = norm([group.group, group.source, group.use]).includes(query);
			return headerHit || entries.length ? { ...group, matched_entries: entries.slice(0, limit) } : null;
		})
		.filter((group): group is NonNullable<typeof group> => group !== null);

	return { total: matched.length, groups: matched };
}

export interface FindDeadRouteOptions {
	url?: string;
	source?: string;
	status?: string;
	limit?: number;
}

export function findDeadRoute(options: FindDeadRouteOptions = {}) {
	const limit = Math.max(1, Math.min(options.limit ?? 25, 99));
	let routes = DEAD_ROUTES;

	if (options.url) {
		const wanted = options.url.trim().replace(/\/+$/, '');
		const exact = routes.filter((route) => route.old.replace(/\/+$/, '') === wanted);
		const prefix = routes.filter((route) => {
			if (exact.includes(route)) return false;
			const old = route.old.replace(/\/+$/, '');
			return old.startsWith(wanted) || wanted.startsWith(old);
		});
		routes = [...exact, ...prefix];
	}
	if (options.source) routes = routes.filter((route) => route.source === options.source);
	if (options.status) {
		const status = norm(options.status);
		routes = routes.filter((route) => norm(route.status) === status);
	}

	return {
		total: routes.length,
		routes: routes.slice(0, limit).map((route) => ({
			old: route.old,
			status: route.status,
			...(route.new ? { new: route.new } : {}),
			...(route.source ? { source: route.source } : {}),
			...(route.note ? { note: route.note } : {}),
			...(route.checked ? { checked: route.checked } : {}),
		})),
	};
}

export function listIdentifiers(query?: string, limit = 50) {
	const entries = Object.entries(IDENTIFIERS);
	const ordered = query
		? rank(
				query,
				entries,
				([id, identifier]) => ({ strong: norm(id), weak: norm([identifier.format, identifier.issuer]) }),
				limit,
			)
		: entries.slice(0, Math.max(1, Math.min(limit, 50)));

	return {
		total: ordered.length,
		identifiers: ordered.map(([id, identifier]) => ({
			id,
			format: identifier.format,
			example: identifier.example,
			issuer: identifier.issuer,
			...(identifier.gotcha ? { gotcha: identifier.gotcha } : {}),
		})),
	};
}

function countBy(values: string[]): Record<string, number> {
	const counts: Record<string, number> = {};
	for (const value of values) counts[value] = (counts[value] ?? 0) + 1;
	return Object.fromEntries(Object.entries(counts).sort((a, b) => b[1] - a[1]));
}

export function catalogSummary() {
	const sectors = Object.entries(SECTORS).map(([id, label]) => ({
		id,
		label,
		sources: SOURCES.filter((source) => source.sector === id).length,
	}));

	return {
		name: catalog.name,
		description: catalog.description,
		generated: catalog.generated,
		repo: catalog.repo,
		counts: {
			sources: SOURCES.length,
			products: PRODUCTS.length,
			recipes: RECIPES.length,
			needs: NEEDS.length,
			identifiers: Object.keys(IDENTIFIERS).length,
			dead_routes: DEAD_ROUTES.length,
			code_groups: Object.keys(CODE_GROUPS).length,
		},
		levels: countBy(SOURCES.map((source) => source.level)),
		statuses: countBy(SOURCES.map((source) => source.status)),
		auth: countBy(SOURCES.map((source) => source.auth)),
		access: countBy(SOURCES.flatMap((source) => source.access)),
		formats: countBy(SOURCES.flatMap((source) => source.formats)),
		sectors,
	};
}
